'use client';
import { useState } from 'react';
import SteamProfileSearch from './components/SteamProfileSearch';
import SteamPlayerCard from './components/SteamPlayerCard';

export default function SearchPage() {
  const [steamId, setSteamId] = useState<string | null>(null);

  const handleProfileFound = (id: string) => {
    setSteamId(id);
  };

  return (
    <div className="container mx-auto p-4">
      <h1 className="text-2xl font-bold mb-6">Buscar Perfil de Steam</h1>
      
      <SteamProfileSearch 
        onProfileFound={handleProfileFound} 
        className="mb-8"
      />
      
      {steamId && (
        <div className="mt-8">
          <h2 className="text-xl font-semibold mb-4">Perfil encontrado:</h2>
          <SteamPlayerCard steamId={steamId} />
        </div>
      )}
    </div>
  );
}